using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class FinishPoolLip{public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var race=Object.FindAnyObjectByType<RaceDirector>();var c=race.GetComponent<BackyardForwardCourse>();var lip=c.flightStarts[2];var axis=c.flightDirections[2];var flags=BindingFlags.Static|BindingFlags.NonPublic;
typeof(Racer.Editor.BackyardReverseAuthoring).GetMethod("Sculpt",flags).Invoke(null,new object[]{(Func<Vector3,bool>)(p=>{float a=Vector3.Dot(p-lip,axis),d=Mathf.Abs(Vector3.Dot(p-lip,Vector3.Cross(Vector3.up,axis)));return a>-.9f&&a<3.5f&&d<5.3f;}),(Func<Vector3,Vector3>)(p=>{float a=Vector3.Dot(p-lip,axis),d=Mathf.Abs(Vector3.Dot(p-lip,Vector3.Cross(Vector3.up,axis)));p.y=Mathf.Lerp(p.y,Mathf.Min(p.y,86.15f+a*.08f),1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.65f,5.3f,d)));return p;}),"Remove former pool crest remnant"});Physics.SyncTransforms();var rows=new System.Collections.Generic.List<string>();float best=-999;Vector3 newLip=lip;for(float a=-.7f;a<2;a+=.025f){var p=lip+axis*a;p.y=Racer.Editor.BackyardReverseAuthoring.Ground(p);rows.Add($"{a:F3} {p:F3}");if(p.y>best){best=p.y;newLip=p;}}c.flightStarts[2]=newLip;c.launchStations[2]=race.road.Project(newLip,out _);Object.FindAnyObjectByType<ForestLayout>().jumpStarts=c.launchStations;EditorUtility.SetDirty(c);EditorSceneManager.MarkSceneDirty(race.gameObject.scene);EditorSceneManager.SaveScene(race.gameObject.scene);AssetDatabase.SaveAssets();rows.Add("Final actual lip="+newLip);File.WriteAllLines("Docs/SevenCorrections/pool-lip-samples.txt",rows);return "Removed remaining original crest collision; actual lip "+newLip;}}
